income_tasks={
'42762':('Income shares from the poorest to richest quintile are 3%, 8%, 14%, 25%, and 50%. What share belongs to the richest 20%?', ['25%','80%','50%','75%'],2,'The richest quintile is the highest-income fifth of the population, whose share is 50%.'),
'42766':('The poorest 80% receive 54% of total income. What share goes to the richest quintile?', ['20%','54%','46%','80%'],2,'Income shares total 100%, so the richest quintile receives 100% − 54% = 46%.'),
'42770':('The richest quintile receives 42% of total income. A student labels that group as the richest 42% of people. What is the correct interpretation?', ['42% of people receive 20% of income.','20% of people receive 20% of income.','20% of people receive 42% of income.','42% of people receive 42% of income.'],2,'A quintile is 20% of the population. Its income share need not equal its population share.'),
'42774':('Income shares from poorest to richest are 7%, 12%, 17%, 25%, and 39%. Does the richest quintile receive more income than the poorest two quintiles combined?', ['No; 39% is less than 40%.','No; 25% exceeds 19%.','Yes; 39% exceeds 19%.','Yes; 39% exceeds 7% but not 19%.'],2,'The poorest two quintiles receive 7% + 12% = 19%; the richest receives 39%.'),
'42778':('The richest quintile receives 44% of an economy’s $500 million total income. How much income does it receive?', ['$100 million','$280 million','$220 million','$440 million'],2,'0.44 × $500 million = $220 million.'),
'42782':('The richest quintile’s share falls from 48% to 43%, with total income unchanged. By how many percentage points does the combined share of the other four quintiles rise?', ['43','10.4','5','48'],2,'The remaining share rises from 52% to 57%, an increase of 5 percentage points.'),
'42763':('Income shares from poorest to richest are 4%, 11%, 18%, 27%, and 40%. What cumulative income share belongs to the poorest 40%?', ['11%','40%','29%','15%'],3,'The bottom 40% comprises two quintiles: 4% + 11% = 15%.'),
'42767':('The bottom quintile receives 6% of income and the bottom 40% receive 19%. What share belongs to the second quintile alone?', ['19%','25%','40%','13%'],3,'Subtract the first quintile from the cumulative share: 19% − 6% = 13%.'),
'42771':('Quintile income shares from poorest to richest are 2%, 9%, 16%, 28%, and 45%. Which point belongs on the Lorenz curve at a population share of 60%?', ['(60%, 16%)','(60%, 60%)','(60%, 45%)','(60%, 27%)'],3,'The poorest three quintiles receive 2% + 9% + 16% = 27%.'),
'42775':('Quintile income shares from poorest to richest are 5%, 12%, 18%, 25%, and 40%. A student uses 12% as the cumulative share of the bottom 40%. What was omitted?', ['The richest quintile’s 40% share.','The third quintile’s 18% share.','The population share of 40%.','The poorest quintile’s 5% share.'],3,'The cumulative bottom-40% share includes the first two quintiles: 5% + 12% = 17%.'),
'42779':('The bottom 40% receive 18% of total income, while the bottom 60% receive 36%. What share belongs to the middle quintile?', ['36%','54%','20%','18%'],3,'The middle quintile is the additional population from 40% to 60%: 36% − 18% = 18%.'),
'42783':('Quintile shares are 6%, 13%, 18%, 26%, and 37%, from poorest to richest. The total income is $200 million. How much goes to the bottom 40%?', ['$26 million','$40 million','$74 million','$38 million'],3,'The bottom 40% receive 6% + 13% = 19%; 0.19 × $200 million = $38 million.'),
'42764':('The bottom four quintiles receive 4%, 10%, 17%, and 24% of income. What share belongs to the richest quintile?', ['45%','55%','24%','76%'],0,'The listed shares total 55%; the remaining share is 100% − 55% = 45%.'),
'42768':('The richest quintile receives 38% of income. What share is received by the other four quintiles combined?', ['62%','38%','80%','20%'],0,'All income shares sum to 100%; 100% − 38% = 62%.'),
'42772':('An income table lists quintile shares of 3%, 9%, 16%, 27%, and 42%. The first four entries are correct. What should the last entry be?', ['45%','42%','55%','58%'],0,'The first four shares sum to 55%; the last must be 45% to make the total 100%.'),
'42776':('The bottom four quintiles together receive 57% of total income. Does the richest quintile receive a majority of all income?', ['No; its share is 43%.','Yes; its share is 57%.','Yes; its population share is 20%.','No; its income share must be 20%.'],0,'The richest quintile receives 100% − 57% = 43%, below one-half.'),
'42780':('The bottom four quintiles receive 8%, 13%, 18%, and 26% of income. Their economy earns $400 million in total. How much income belongs to the richest quintile?', ['$140 million','$260 million','$104 million','$80 million'],0,'The listed shares sum to 65%, leaving 35%; 0.35 × $400 million = $140 million.'),
'42769':('The richest quintile receives 48% of income and the poorest receives 8%. How many times as large is the richest quintile’s share?', ['Four','Six','Forty','Fifty-six'],1,'48% ÷ 8% = 6.'),
'42773':('The richest quintile receives seven times the poorest quintile’s share. If the poorest receives 6%, what share does the richest receive?', ['13%','42%','7%','36%'],1,'7 × 6% = 42%.'),
'42781':('The richest quintile receives 40% of income and the poorest receives 4%. A transfer changes these shares to 36% and 6%, respectively. What happens to their share ratio?', ['It falls from 10 to 9.','It falls from 10 to 6.','It rises from 10 to 12.','It stays at 10.'],1,'The initial ratio is 40/4 = 10; the new ratio is 36/6 = 6.')}
